code.cpp:
class Solution {
public:
    int findMaximumXOR(vector<int>& nums) {
        int max_xor = 0;
        int mask = 0;

        for (int i = 30; i >= 0; --i) {
            mask |= (1 << i);
            int target = max_xor | (1 << i);

            unordered_set<int> prefixes;
            for (int num : nums) {
                prefixes.insert(num & mask);
            }

            for (int p : prefixes) {
                if (prefixes.count(p ^ target)) {
                    max_xor = target;
                    break;
                }
            }
        }

        return max_xor;
    }
};
